use super::*;

fn library_fixture() -> Fixture {
    let fixture = Fixture::new();
    fs::write(
        fixture.root.join("Cargo.lock"),
        "# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\nversion = 4\n\n[[package]]\nname = \"eqiora-numerics\"\nversion = \"0.0.0\"\n",
    )
    .unwrap();
    fs::write(
        fixture.root.join("eqiora-numerics/src/lib.rs"),
        r#"
#[cfg(test)]
mod private_parent {
    mod private_child {
        #[test]
        fn registered_evidence() {
            use std::io::Write as _;
            let mut marker = std::fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open("selected.marker")
                .unwrap();
            writeln!(marker, "selected").unwrap();
        }

        #[test]
        fn registered_evidence_extra() {
            std::fs::write("substring.marker", "substring also ran\n").unwrap();
        }

        #[test]
        #[ignore = "registered evidence must reject ignored tests"]
        fn ignored_evidence() {
            std::fs::write("ignored.marker", "ignored test ran\n").unwrap();
        }

        #[test]
        fn failing_evidence() {
            panic!("frozen private oracle failure");
        }
    }
}
"#,
    )
    .unwrap();
    fixture
}

fn valid_library_manifest() -> &'static str {
    r#"
id = "area.case"
status = "verified"
reference_kind = "compiler-contract"
capabilities = ["private-library-oracle"]

[evidence]
runner = "cargo-library-test"
package = "eqiora-numerics"
test = "private_parent::private_child::registered_evidence"
features = ["one", "two"]
table = "expected/evidence.csv"
"#
}

fn library_target_with(test: &str, features: &[&str]) -> EvidenceTarget {
    let features = features
        .iter()
        .map(|feature| format!("\"{feature}\""))
        .collect::<Vec<_>>()
        .join(", ");
    toml::from_str(&format!(
        "runner = \"cargo-library-test\"\npackage = \"eqiora-numerics\"\ntest = \"{test}\"\nfeatures = [{features}]\n"
    ))
    .unwrap()
}

